<script setup>
import {inject as injectAdminConfirmation} from 'vue'
const {confirmAction}=injectAdminConfirmation('admin')
import AdminFilterSummary from '../../components/admin/AdminFilterSummary.vue'
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue'
import {useModalDraft} from '../../composables/useModalDraft'
import DomainFilters from '../../components/admin/DomainFilters.vue'
import {cmsFilters} from '../../constants/domainFilters'
import {ref,reactive,computed,watch,inject} from 'vue'
import {cmsAdminApi} from '../../api/cms.api'
import {cmsFields,sectionFields} from '../../constants/cmsFields'
import {utcInput,utcPayload} from '../../utils/formDates'
import {useAuthStore} from '../../stores/auth'
import {useServerList} from '../../composables/useServerList'
import {useApiState,useApiMutation} from '../../composables/useApiState'
import AdminModal from '../../components/admin/AdminModal.vue'
import DomainFields from '../../components/admin/DomainFields.vue'
import CmsGalleryEditor from '../../components/admin/CmsGalleryEditor.vue'
import ApiFeedback from '../../components/admin/catalog/ApiFeedback.vue'
import ApiPagination from '../../components/admin/catalog/ApiPagination.vue'
const auth=useAuthStore(),{notify}=inject('admin'),kinds=['pages','banners','gallery'],tab=ref(kinds.find(k=>auth.can('cms.'+k+'.view'))),api={list:(...args)=>cmsAdminApi(tab.value).list(...args)},list=useServerList(api),detail=useApiState(),sections=useApiState(),mutation=useApiMutation(),open=ref(false),editing=ref(null),section=ref(null),pageRecord=ref(null),form=reactive({}),items=ref([])
const filterDefaults={...list.filters}
const editorSections=[{title:'المحتوى الأساسي',keys:['title','slug','placement','subtitle','description','content','alt_text']},{title:'الصور والوسائط',keys:['image','mobile_image','clear_image','clear_mobile_image','og_image','clear_og_image']},{title:'الأزرار والروابط',keys:['button_text','button_url','secondary_button_text','secondary_button_url','data.primary_button_text','data.primary_button_url','data.secondary_button_text','data.secondary_button_url']},{title:'تحسين ظهور الصفحة',keys:['meta_title','meta_description','canonical_url']},{title:'النشر والترتيب',keys:['status','published_at','starts_at','ends_at','sort_order','is_active','data.limit']}]
const labels={pages:'الصفحات',banners:'البانرات',gallery:'معرض الصور'},fields=computed(()=>section.value?sectionFields(section.value):cmsFields[tab.value].map(f=>({...f,required:f.key==='image'&&!editing.value||tab.value==='pages'&&f.key==='title'||f.required})))
async function edit(row=null,target=null){if(detail.loading.value||sections.loading.value||mutation.busy.value)return;section.value=target;mutation.error.value=null;let value=target||row;if(row&&!target)value=await detail.run(()=>cmsAdminApi(tab.value).show(row.id));if(row&&!value)return;editing.value=target||value;Object.keys(form).forEach(k=>delete form[k]);for(const f of fields.value){const original=f.key.startsWith('data.')?value?.data?.[f.key.slice(5)]:value?.[f.key];form[f.key]=f.type==='file'?null:f.type==='checkbox'?original??false:f.type==='datetime-local'?utcInput(original):original??(f.key==='placement'?'home_hero':f.key==='status'?'draft':f.key==='sort_order'?0:'')};items.value=(value?.data?.items||[]).map(i=>({...i}));open.value=true}
async function showSections(row){if(sections.loading.value||detail.loading.value||mutation.busy.value)return;pageRecord.value=row;await sections.run(signal=>cmsAdminApi('pages').sections(row.id,signal))}
async function save(){if(form.status==='published'&&!(await confirmAction('نشر المحتوى على الموقع العام؟')))return;const payload={};for(const f of fields.value){const value=form[f.key];if(f.key.startsWith('clear_'))continue;if(f.type==='file'){if(value)payload[f.key]=value;continue}if(f.key.startsWith('data.')){if(f.key==='data.limit'&&value==='')continue;payload.data||={};payload.data[f.key.slice(5)]=f.type==='number'?value:value||null}else payload[f.key]=f.type==='datetime-local'?utcPayload(value,editing.value?.[f.key]):f.type==='checkbox'?value:f.type==='number'?value:value||null}for(const key of ['image','mobile_image','og_image'])if(form['clear_'+key]&&!form[key])payload[key]=null;if(section.value?.type==='features')payload.data={items:items.value};const result=await mutation.run(()=>section.value?cmsAdminApi('pages').section(pageRecord.value.id,section.value.id,payload):cmsAdminApi(tab.value).save(editing.value?.id,payload));if(result.ok){open.value=false;notify('تم حفظ المحتوى على الخادم.');if(section.value)showSections(pageRecord.value);else list.load()}}
async function remove(row){if(!(await confirmAction('حذف هذا المحتوى؟')))return;const result=await mutation.run(()=>cmsAdminApi(tab.value).remove(row.id));if(result.ok){notify('تم حذف المحتوى.');list.load()}}
async function move(index,step){const rows=list.state.data.value.data,a=rows[index],b=rows[index+step];if(!b)return;const start=Math.min(a.sort_order,b.sort_order);const result=await mutation.run(()=>cmsAdminApi(tab.value).reorder([{id:a.id,sort_order:step<0?start:start+1},{id:b.id,sort_order:step<0?start+1:start}]));if(result.ok)list.load()}
watch(tab,()=>{sections.clear();pageRecord.value=null;Object.keys(list.filters).forEach(key=>delete list.filters[key]);Object.assign(list.filters,{search:'',per_page:20});list.search()});list.load()
const beforeClose=useModalDraft(open,form,mutation.busy,items)
</script>
<template><main id="main"><AdminPageHeader class="page-heading"><div><span class="eyebrow">إدارة شيشلي</span><h1>محتوى الموقع</h1><p class="muted">النشر وSEO والصور والمحتوى النصي</p></div><button v-if="tab!=='pages'&&auth.can('cms.'+tab+'.create')" class="button" :disabled="mutation.busy.value||detail.loading.value||sections.loading.value" @click="edit()">إضافة {{ tab==='banners'?'بانر':'صورة' }}</button></AdminPageHeader><nav class="module-tabs"><button v-for="kind in kinds.filter(k=>auth.can('cms.'+k+'.view'))" :key="kind" :aria-pressed="tab===kind" :disabled="mutation.busy.value||detail.loading.value||sections.loading.value" @click="tab=kind">{{ labels[kind] }}</button></nav><section class="panel"><form class="toolbar" @submit.prevent="list.search"><input v-model="list.filters.search" type="search" maxlength="150" aria-label="بحث المحتوى" placeholder="بحث في المحتوى"><button class="button" :disabled="list.state.loading.value">بحث</button><DomainFilters @clear="list.search()" :form="list.filters" :fields="cmsFilters(tab)" :busy="list.state.loading.value"/></form><AdminFilterSummary :filters="list.filters" :defaults="filterDefaults" :busy="list.state.loading.value" @clear="Object.assign(list.filters,filterDefaults);list.search()"/><ApiFeedback :loading="list.state.loading.value" :error="list.state.error.value" @retry="list.load"/><ApiFeedback variant="inline" :loading="detail.loading.value" :error="detail.error.value" @retry="detail.error.value=null"/><div v-if="list.state.data.value" class="table-wrap"><table v-admin-table><thead><tr><th>المحتوى</th><th>الحالة / الموضع</th><th>الترتيب</th><th>الإجراءات</th></tr></thead><tbody><tr v-for="(row,index) in list.state.data.value.data" :key="row.id"><td><div class="admin-cell-value"><img v-if="row.image_url" class="cms-image" :src="row.image_url" :alt="row.alt_text||row.title||''">{{ row.title||row.key||'بدون عنوان' }}</div></td><td><div class="admin-cell-value">{{ row.status||row.placement|| (row.is_active?'مفعّل':'متوقف') }}</div></td><td><div class="admin-cell-value">{{ row.sort_order??'—' }}</div></td><td><div class="admin-cell-value"><div class="admin-row-actions"><button v-if="auth.can('cms.'+tab+'.update')" class="row-button" :disabled="mutation.busy.value||detail.loading.value" @click="edit(row)">تعديل</button><button v-if="tab==='pages'" class="row-button" :disabled="mutation.busy.value||detail.loading.value||sections.loading.value" @click="showSections(row)">الأقسام</button><template v-else><button v-if="auth.can('cms.'+tab+'.update')" class="row-button" :disabled="!index||mutation.busy.value" aria-label="تقديم المحتوى" @click="move(index,-1)">↑</button><button v-if="auth.can('cms.'+tab+'.update')" class="row-button" :disabled="index===list.state.data.value.data.length-1||mutation.busy.value" aria-label="تأخير المحتوى" @click="move(index,1)">↓</button><button v-if="auth.can('cms.'+tab+'.delete')" class="row-button danger" :disabled="mutation.busy.value||detail.loading.value||sections.loading.value" @click="remove(row)">حذف</button></template></div></div></td></tr></tbody></table><p v-if="!list.state.data.value.data.length" class="empty">لا يوجد محتوى مطابق.</p></div><ApiPagination :meta="list.state.data.value?.meta" :links="list.state.data.value?.links" :busy="list.state.loading.value" @page="list.changePage"/></section><section v-if="pageRecord" class="panel"><div class="panel-head"><h2>أقسام {{ pageRecord.title }}</h2><button class="row-button" type="button" :disabled="mutation.busy.value||sections.loading.value" @click="pageRecord=null;sections.clear()">إغلاق الأقسام</button></div><ApiFeedback variant="list" :loading="sections.loading.value" :error="sections.error.value" @retry="showSections(pageRecord)"/><div v-if="sections.data.value" class="table-wrap"><table v-admin-table><thead><tr><th>القسم</th><th>نوع المحتوى</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody><tr v-for="row in sections.data.value" :key="row.id"><td><div class="admin-cell-value">{{ row.title||row.key }}</div></td><td><div class="admin-cell-value">{{ row.type }}</div></td><td><div class="admin-cell-value">{{ row.is_active?'مفعّل':'متوقف' }}</div></td><td><div class="admin-cell-value"><button v-if="auth.can('cms.pages.update')" class="row-button" :disabled="mutation.busy.value||detail.loading.value||sections.loading.value" @click="edit(null,row)">تعديل القسم</button></div></td></tr></tbody></table></div></section><ApiFeedback v-if="!open" :error="mutation.error.value" @retry="mutation.error.value=null"/><AdminModal size="large" :before-close="beforeClose" v-model:open="open" :title="section?'تعديل القسم':tab==='gallery'?(editing?'تعديل صورة المعرض':'إضافة صورة للمعرض'):editing?'تعديل المحتوى':'إضافة محتوى'" :busy="mutation.busy.value" @submit="save"><CmsGalleryEditor v-if="tab==='gallery'&&!section&&open" :form="form" :fields="fields" :existing-image="editing?.image_url" :errors="mutation.error.value?.errors" :disabled="mutation.busy.value"/><DomainFields v-else :sections="editorSections" :fields="fields" :form="form" :errors="mutation.error.value?.errors" :disabled="mutation.busy.value"/><template v-if="section?.type==='features'"><h3>بطاقات المميزات</h3><div v-for="(item,index) in items" :key="index" class="audit-item-form"><label class="field">العنوان<input v-model="item.title" required maxlength="150" :disabled="mutation.busy.value"></label><label class="field">الوصف<textarea v-model="item.description" maxlength="1000" :disabled="mutation.busy.value"/></label><button type="button" class="row-button danger" :disabled="mutation.busy.value||detail.loading.value||sections.loading.value" @click="items.splice(index,1)">إزالة البطاقة</button></div><button type="button" class="row-button" :disabled="items.length>=12||mutation.busy.value" @click="items.push({title:'',description:''})">إضافة بطاقة</button></template><ApiFeedback :error="mutation.error.value" @retry="mutation.error.value=null"/><p class="form-note">التواريخ بتوقيت UTC؛ اترك حقل الصورة فارغًا للحفاظ على الصورة الحالية. المحتوى نصي ولا يدعم HTML.</p><button class="button" :disabled="mutation.busy.value">حفظ المحتوى</button></AdminModal></main></template>
